TLM.f("Sancti/03-24",{"officium":"S. Gabrielis Archangeli","rule":["Gloria","CredoDa"],"sections":{"Introitus":[{"k":"ref","la":"Ps 102:20"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 102:1"},{"k":"text","la":"Bénedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui inter céteros Angelos, ad annuntiándum incarnatiónis tuæ mystérium, Gabriélem Archángelum elegísti: concéde propítius; ut, qui festum (commemoratiónem) ejus celebrámus in terris, ipsíus patrocínium sentiámus in cœlis:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Daniélis Prophétæ"},{"k":"ref","la":"Dan 9:21-26"},{"k":"text","la":"In diébus illis: Ecce, vir Gábriël, quem víderam m visióne a princípio, cito volans tétigit me in témpore sacrifícii vespertíni. Et dócuit me et locútus est mihi dixítque: Dániel, nunc egréssus sum, ut docérem te et intellégeres. Ab exórdio precum tuárum egréssus est sermo: ego autem veni, ut indicárem tibi, quia vir desideriórum es: tu ergo animadvérte sermónem et intéllege visiónem. Septuagínta hebdómades abbreviátæ sunt super pópulum tuum et super urbem sanctam tuam, ut consummétur prævaricátio, et finem accípiat peccatum, et deleátur iníquitas, et adducátur justítia sempitérna, et impleátur visio et prophetia, et ungátur Sanctus sanctórum. Scito ergo et animadvérte: Ab éxitu sermónis, ut íterum ædificétur Jerúsalem, usque ad Christum ducem, hebdómades septem et hebdómades sexagínta duæ erunt: et rursum ædificábitur platéa et muri in angustia temporum. Et post hebdómades sexagínta duas occidétur Christus: et non erit ejus pópulus, qui eum negatúrus est. Et civitátem et sanctuárium dissipábit populus cum duce ventúro: et finis ejus vástitas, et post finem belli statúta desolátio."}],"Graduale":[{"k":"ref","la":"Ps 102:20 et 1"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus."},{"k":"text","la":"Benedic, ánima mea, Dóminum, et ómnia interióra mea nomen sanctum ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 102:21"},{"k":"text","la":"Benedicite Dómino, omnes virtútes ejus: ministri ejus, qui fácitis voluntátem ejus. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 103:4"},{"k":"text","la":"Qui facit Angelos suos spíritus: et minístros suos flammam ignis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 102:20 et 1"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus."},{"k":"text","la":"Benedic, ánima mea, Dóminum, et ómnia interióra mea nomen sanctum ejus.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Luc 1:28, 42, 31 et 35"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum."},{"k":"text","la":"Benedícta tu in muliéribus: et benedíctus fructus ventris tui.","mark":"V"},{"k":"text","la":"Ecce, concípies et páries Fílium, et vocábis nomen ejus Emmánuel.","mark":"V"},{"k":"text","la":"Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi.","mark":"V"},{"k":"text","la":"Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:26-38"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriel a Deo in civitátem Galilææ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David. et nomen Vírginis María. Ei ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero et páries fílium, et vocábis nomen ejus Jesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David, patris ejus: et regnábit in domo Jacob in ætérnum, et regni ejus non erit finis. Dixit autem María ad Angelum: Quómodo fiet istud, quóniam virum non cognósco? Et respóndens Angelus, dixit ei: Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi. Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei. Et ecce, Elísabeth, cognáta tua, et ipsa concépit fílium in senectúte sua: et hic mensis sextus est illi, quæ vocátur stérilis: quia non erit impossíbile apud Deum omne verbum. Dixit autem María: Ecce ancílla Dómini, fiat mihi secúndum verbum tuum."}],"Offertorium":[{"k":"ref","la":"Apoc 8:3 et 4"},{"k":"text","la":"Stetit Angelus juxta aram templi, habens thuríbulum áureum in manu sua, et data sunt ei incénsa multa: et ascéndit fumus aromátum in conspéctu Dei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Accéptum fiat in conspéctu tuo, Dómine, nostræ servitútis munus, et beáti Archángeli Gabriélis orátio: ut, qui a nobis venerátur in terris, sit apud te pro nobis advocátus in cœlis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Dan 3:58"},{"k":"text","la":"Benedicite, omnes Angeli Dómini, Dóminum: hymnum dícite et superexaltáte eum in sǽcula. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Córporis tui et Sánguinis sumptis mystériis, tuam, Dómine, Deus noster, deprecámur cleméntiam: ut, sicut, Gabriéle nuntiánte, incarnatiónem tuam cognóvimus; ita, ipso adjuvante, incarnationis ejúsdem benefícia consequámur:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"20371728e8e07793":{"t":"<i>Pomolimo se</i>.\nBože, koji si za navještenje otajstva svoga utjelovljenja među ostalim anđelima izabrao Gabrijela Arkanđela, podaj milostivo, da slaveći njegov blagdan [spomen] na zemlji osjetimo njegov zagovor u nebu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","v":"∅ → comemorationem"},"2f95c2b2e3171eb6":{"t":"Neka ti se, Gospodine, svidi dar naše službe i molitva blaženoga Arkanđela Gabrijela, da po nama štovan na zemlji bude naš zagovornik kod tebe na nebesima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]"},"99a4aede0c83fdb0":{"t":"<i>Pomolimo se</i>.\nPrimivši otajstva Tijela i krvi, milost tvoju molimo, Gospodine Bože naš, da kao što smo po navještenju Gabrijela spoznali tvoje utjelovljenje, dobročinstva istog utjelovljenja primimo po njegovom zagovoru:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]"}}});
